350	        OwnerPageDto ownerPageDto = new OwnerPageDto();
351	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
352	        ownerPageDto.setPage(ownerPage.getNumber());
353	        ownerPageDto.setSize(ownerPage.getSize());
354	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
355	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
356	        return ownerPageDto;
357	    }
358	}
