312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
316	        Owner owner = this.clinicService.findOwnerById(ownerId);
317	        if (owner != null) {
318	            Pet pet = owner.getPet(petId);
319	            if (pet != null) {
320	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
321	            }
322	        }
323	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
324	    }
325	
326	    /**
327	     * Loads the owner with the given id and, when it exists, produces the response through
328	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
329	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
330	     * the not-found response are written in exactly one place rather than copied into each method.
331	     *
332	     * @param ownerId the id of the owner to load
333	     * @param action builds the response for an existing owner
334	     * @param <T> the response body type
335	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
336	     */
337	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
338	        Owner owner = this.clinicService.findOwnerById(ownerId);
339	        if (owner == null) {
340	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
341	        }
342	        return action.apply(owner);
343	    }
344	
345	    /**
346	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
347	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag,
348	     * the {@code identityKey} and the {@code possibleDuplicate} pair), and re-applies the owner's
349	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
350	     * create endpoint and the single-owner read endpoint return their owner through this method, so
351	     * an owner is decorated identically on either path and each derived field is computed in exactly
352	     * one place.
353	     *
354	     * @param owner the persisted owner to represent
355	     * @return the owner DTO with its derived read-only fields populated
356	     */
357	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
358	        owner.setHouseholdSize(householdSize(owner));
359	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
360	        ownerDto.setMembershipLevel(membershipLevel(owner));
361	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
362	        ownerDto.setIdentityKey(identityKey(owner));
363	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
364	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
365	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
366	        return ownerDto;
367	    }
368	
369	    /**
370	     * The {@code membershipLevel} reported for a single owner. Delegates to the owner-local
371	     * derivation in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own
372	     * membership points), routed through the controller so the create audit log and the single-owner
373	     * response agree on one value. Unlike the mapper - which sees only the owner - the controller can
374	     * reach the rest of the clinic, so this is the single place a reported membership level is shaped
375	     * by cross-owner context (such as the owner's {@link #householdMembers(Owner) household}).
376	     *
377	     * @param owner the owner whose reported membership level is wanted
378	     * @return the owner's membership level
379	     */
380	    private Integer membershipLevel(Owner owner) {
381	        return ownerMapper.membershipLevel(owner);
382	    }
383	
384	    /**
385	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
386	     * every later step - the required-field check, the persisted value and the response - sees the
387	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
388	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
389	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
390	     * steps that read the address.
391	     *
392	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
393	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
394	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
395	     * are preferred when present: the flat {@code address} returned is composed as the normalized
396	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
397	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
398	     * {@code address} retain its own normalized value.
399	     *
400	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
401	     */
402	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
403	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
404	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
405	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
406	        ownerFieldsDto.setAddressLine1(addressLine1);
407	        ownerFieldsDto.setAddressLine2(addressLine2);
408	        if (addressLine1 != null && !addressLine1.isBlank()) {
409	            String composed = addressLine2 != null && !addressLine2.isBlank()
410	                ? addressLine1 + " " + addressLine2
411	                : addressLine1;
412	            ownerFieldsDto.setAddress(composed);
413	        } else {
414	            ownerFieldsDto.setAddress(flatAddress);
415	        }
416	    }
