418	    /**
419	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
420	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
421	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
422	     * blank (e.g. {@code "   "}). The offending field names are reported through an
423	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
424	     * as a 400 response carrying an {@code errors} array of field names.
425	     *
426	     * @param ownerFieldsDto the submitted owner fields
427	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
428	     */
429	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
430	        List<String> blankFields = new ArrayList<>();
431	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
432	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
433	        addRequiredAddress(blankFields, ownerFieldsDto);
434	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
435	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
436	        if (!blankFields.isEmpty()) {
437	            throw new InvalidOwnerFieldsException(blankFields);
438	        }
439	    }
