456	     * @param ownerFieldsDto the submitted owner fields
457	     */
458	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
459	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
460	            blankFields.add("address");
461	        }
