497	     * @param city the city of the owner being created
498	     * @param postcode the supplied postcode, or {@code null} when omitted
499	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
500	     */
501	    private void rejectInvalidPostcode(String city, String postcode) {
502	        if (postcode == null || postcode.isBlank()) {
503	            return;
504	        }
505	        Region.forCity(city).ifPresent(region -> {
