512	    /**
513	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
514	     * the {@code customerCode}.
515	     */
516	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
517	
518	    /**
519	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
520	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
521	     * its {@code postcode} (falling back to its {@code city}) through the shared
522	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
523	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
524	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
525	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
526	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
527	     * distinct customer codes.
528	     *
529	     * @param owner the owner being created, with its telephone already normalized
530	     * @return the formatted, de-duplicated customer code
531	     */
532	    private String customerCode(Owner owner) {
533	        String region = Region.code(owner.getPostcode(), owner.getCity());
534	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
535	        String base = region + "-" + hash8;
536	        return deduplicateCustomerCode(base);
537	    }
538	
539	    /**
540	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
541	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
542	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
543	     * held by no existing owner.
544	     *
545	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
546	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
547	     */
548	    private String deduplicateCustomerCode(String base) {
549	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
550	            .map(Owner::getCustomerCode)
551	            .filter(java.util.Objects::nonNull)
552	            .collect(java.util.stream.Collectors.toSet());
553	        if (!existing.contains(base)) {
554	            return base;
555	        }
556	        int n = 2;
557	        while (existing.contains(base + "-" + n)) {
558	            n++;
559	        }
560	        return base + "-" + n;
561	    }
