656	    /**
657	     * The fixed list of public holidays that are not business days. A registration date that lands
658	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
659	     * business day, exactly as it is rolled forward off a weekend.
660	     */
661	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
662	        LocalDate.of(2026, 1, 1),
663	        LocalDate.of(2026, 1, 26),
664	        LocalDate.of(2026, 4, 25),
665	        LocalDate.of(2026, 12, 25),
666	        LocalDate.of(2026, 12, 28));
