668	    /**
669	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
670	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
671	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
672	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
673	     * value - whether supplied in the request or defaulted to the server date - is stored as the
674	     * next business day, and every value derived from the registration date (such as the membership
675	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
676	     *
677	     * @param date the effective registration date
678	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
679	     */
680	    private LocalDate businessDay(LocalDate date) {
681	        while (isNonBusinessDay(date)) {
682	            date = date.plusDays(1);
683	        }
684	        return date;
685	    }
