687	    /**
688	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
689	     *
690	     * @param date the date to test
691	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
692	     */
693	    private boolean isNonBusinessDay(LocalDate date) {
694	        DayOfWeek dayOfWeek = date.getDayOfWeek();
695	        return dayOfWeek == DayOfWeek.SATURDAY
696	            || dayOfWeek == DayOfWeek.SUNDAY
697	            || PUBLIC_HOLIDAYS.contains(date);
698	    }
