701	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
702	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
703	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
704	     * renders as a 429 Too Many Requests response.
705	     *
706	     * @param date the registration date of the owner being created (today)
707	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
708	     */
709	    private void rejectDailyRegistrationLimit(LocalDate date) {
710	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
711	            throw new DailyOwnerRegistrationLimitException(date);
