762	     * @param owner the fully-populated owner being created (telephone, email and household id set)
763	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
764	     */
765	    private void rejectDuplicateIdentity(Owner owner) {
766	        String key = identityKey(owner);
767	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
768	        if (duplicate) {
769	            throw new DuplicateOwnerIdentityException(key);
770	        }
