788	        if (sharesHousehold) {
789	            return;
790	        }
791	        String household = owner.getHouseholdId();
792	        if (household == null) {
793	            return;
794	        }
795	        if (existingOwnerMatches(this::householdId, household)) {
796	            throw new DuplicateOwnerIdentityException(identityKey(owner));
