800	    /**
801	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
802	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
803	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
804	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
805	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
806	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
807	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
808	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
809	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
810	     *
811	     * @param owner the fully-populated owner being created (telephone normalized)
812	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
813	     */
814	    private Integer possibleDuplicateOf(Owner owner) {
815	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
816	            return null;
817	        }
818	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
819	        return this.clinicService.findAllOwners().stream()
820	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
821	                && owner.getPostcode().equals(existing.getPostcode())
822	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
823	            .map(Owner::getId)
824	            .filter(java.util.Objects::nonNull)
825	            .findFirst()
826	            .orElse(null);
827	    }
