829	    /**
830	     * Reduces an owner to its derived {@code identityKey}, formatted
831	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
832	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
833	     * normalized (lower-cased) email or the empty string when absent (see
834	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
835	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
836	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
837	     * single duplicate check compares this one value across owners.
838	     *
839	     * @param owner the owner to derive the identity key for
840	     * @return the owner's identity key
841	     */
842	    private String identityKey(Owner owner) {
843	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
844	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
845	        String email = normalizedEmail == null ? "" : normalizedEmail;
846	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
847	        return telephone + "|" + email + "|" + household;
848	    }
