850	    /**
851	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
852	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
853	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
854	     * checks reduce both an existing owner and the owner being created to the same canonical key;
855	     * this returns the matched existing owner itself, so a caller can either reject the collision or
856	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
857	     * collision with only a deleted owner is not reported and the create is allowed.
858	     *
859	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
860	     * @param key the canonical key of the owner being created
861	     * @return the first existing owner sharing the key, or empty when none does
862	     */
863	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
864	        return this.clinicService.findAllOwners().stream()
865	            .filter(owner -> !owner.isDeleted())
866	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
867	            .findFirst();
868	    }
869	
870	    /**
871	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
872	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
873	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
874	     * being created to the same canonical key and reject a match.
875	     *
876	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
877	     * @param key the canonical key of the owner being created
878	     * @return {@code true} if some existing owner shares the key
879	     */
880	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
881	        return findExistingOwner(keyExtractor, key).isPresent();
882	    }
883	
884	    /**
885	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
886	     * count-based rules - the per-city capacity, the per-day create limit and the derived
887	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
888	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
889	     * place and each rule supplies just its own predicate.
890	     *
891	     * @param predicate the condition an owner must satisfy to be counted
892	     * @return the number of existing owners that satisfy the predicate
893	     */
894	    private long countOwners(Predicate<Owner> predicate) {
895	        return this.clinicService.findAllOwners().stream()
896	            .filter(predicate)
897	            .count();
898	    }
899	
900	    /**
901	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
902	     * shared {@code householdId}.
903	     */
904	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
905	
906	    /**
907	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
908	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
909	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
910	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
911	     *
912	     * @param value the raw field value, or {@code null}
913	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
914	     */
915	    private String canonicalizeHousehold(String value) {
916	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
917	    }
918	
919	    /**
920	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
921	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
922	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
923	     * for the last-name normalization), so every owner with the same last name and postcode -
924	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
925	     * a postcode have no household basis and are given no household id ({@code null}).
926	     *
927	     * @param owner the owner being created
928	     * @return the shared household identifier, or {@code null} when the owner has no postcode
929	     */
930	    /**
931	     * Counts the owners in the given owner's household: the existing owners that share its
932	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
933	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
934	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
935	     * household factor of the owner's membership points.
936	     *
937	     * @param owner the owner whose household size is being derived
938	     * @return the number of owners in the owner's household (at least {@code 1})
939	     */
940	    private int householdSize(Owner owner) {
941	        if (owner.getHouseholdId() == null) {
942	            return 1;
943	        }
944	        return householdMembers(owner).size();
945	    }
946	
947	    /**
948	     * The existing owners that make up the given owner's household: those sharing its
949	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
950	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
951	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
952	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
953	     * counts it among its household, while one taken before the save sees only the owners already
954	     * present. Holding the household lookup in one place lets every household-derived value read the
955	     * same set of members.
956	     *
957	     * @param owner the owner whose household members are wanted
958	     * @return the owners sharing the owner's household, or an empty list when it has no household
959	     */
960	    private List<Owner> householdMembers(Owner owner) {
961	        String household = owner.getHouseholdId();
962	        if (household == null) {
963	            return List.of();
964	        }
965	        return this.clinicService.findAllOwners().stream()
966	            .filter(existing -> household.equals(existing.getHouseholdId()))
967	            .toList();
968	    }
969	
970	    private String householdId(Owner owner) {
971	        String postcode = owner.getPostcode();
972	        if (postcode == null || postcode.isBlank()) {
973	            return null;
974	        }
975	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
976	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
977	    }
978	
979	    /**
980	     * Number of leading hex characters of the household hash retained as the shared
981	     * {@code householdId}.
982	     */
983	    private static final int HOUSEHOLD_ID_LENGTH = 12;
984	
985	    /**
986	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
987	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
988	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
989	     * so every such identifier is produced by the same algorithm and differs only in the value it
990	     * hashes and the number of hex characters it keeps.
991	     *
992	     * @param input the value to hash
993	     * @param length the number of leading hex characters to keep
994	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
995	     */
996	    private String hashPrefix(String input, int length) {
997	        try {
998	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
999	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
1000	            StringBuilder sb = new StringBuilder(digest.length * 2);
1001	            for (byte b : digest) {
1002	                sb.append(String.format("%02X", b));
1003	            }
1004	            return sb.substring(0, length);
1005	        } catch (java.security.NoSuchAlgorithmException e) {
1006	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1007	        }
1008	    }
1009	}
